const contentUnits: SchoolUnit[] = programmeRows.map((row, index) => {
  const [slug, intro, keyIdea, example, question, answer, objective, visual = 'concept'] = starts[index];
  return {
    id: `program-${row.subject}-${row.grade}-${slug}`, subject: row.subject, grade: row.grade,
    order: index + 1, section: row.section, title: row.title,
    topics: row.topics, sourceId: `edsoo-program-${row.subject}-${row.grade < 10 ? '8-9' : '10-11'}-2025`,
    pages: row.pages, objectives: [objective], intro, keyIdea, example, question, answer, visual, notes: note,
  };
});
